            frame.content,
            CANCEL,
            150,

            --[[APR_DIAG]]
            APRTrace(
                "APR-Core/integrations/GamepadControls.lua:106:callback#8", --[[/APR_DIAG]]
                function() self:CancelMenuBinding() end --[[APR_DIAG]]
            ) --[[/APR_DIAG]]
        )
        cancel:SetPoint("BOTTOMRIGHT")
        frame:EnableKeyboard(true)
        frame:SetPropagateKeyboardInput(false)
